import json
import logging
import pathlib

FEATURE_FILE = pathlib.Path("/etc/scoring/http_requests_features.json")

SLOTS = [0.0] * 200
MAX_FEATURES = 200
SCHEMA_VERSION = 2

log = logging.getLogger(__name__)
_last_good = None


class ArtifactRejected(Exception):
    """The generated artifact did not satisfy the contract, so it is not ingested."""


def validate_features(raw):
    """Ingest a first-party generated artifact with the same suspicion as user input."""
    if raw.get("schema_version") != SCHEMA_VERSION:
        raise ArtifactRejected(f"unexpected schema_version {raw.get('schema_version')!r}")
    features = raw.get("features")
    if not isinstance(features, list) or not features:
        raise ArtifactRejected("features must be a non-empty list")
    if len(features) > MAX_FEATURES:
        raise ArtifactRejected(f"{len(features)} features exceeds MAX_FEATURES={MAX_FEATURES}")
    names = [f["name"] for f in features]
    if len(set(names)) != len(names):
        raise ArtifactRejected("duplicate feature rows: the generating query changed shape")
    return features


def load_features():
    """Reject a bad artifact and keep serving on the last known good one."""
    global _last_good
    try:
        _last_good = validate_features(json.loads(FEATURE_FILE.read_text()))
    except (ArtifactRejected, ValueError, KeyError, OSError) as exc:
        log.error("feature artifact rejected, serving last known good: %s", exc)
        if _last_good is None:
            raise
    return _last_good


def score(request, model):
    features = load_features()
    for i, feature in enumerate(features):
        SLOTS[i] = request.get(feature["name"], 0.0)
    return model.predict(SLOTS)
